// Pull each query's rows by node name, so order never matters
const rows = name => {
  try { return $(name).all().map(i => i.json); } catch (e) { return []; }
};

const duplicates = rows('Q1 duplicates');
const incomplete = rows('Q2 incomplete');
const stale      = rows('Q3 stale deals');
const funnel     = rows('Q4 funnel');
const issues     = rows('Q5 deal issues');

const num = v => Number(v) || 0;

// Totals computed here, so the model never has to do arithmetic
const staleCount = stale.reduce((s, r) => s + num(r.stale_deals), 0);
const staleValue = stale.reduce((s, r) => s + num(r.value_at_risk), 0);
const worstOwner = stale.length ? stale[0].owner : null;

const stageCount = s => num((funnel.find(r => r.stage === s) || {}).deals);
const openDeals  = funnel.filter(r => !String(r.stage).startsWith('Closed'))
                         .reduce((s, r) => s + num(r.deals), 0);
const won  = stageCount('Closed Won');
const lost = stageCount('Closed Lost');
const demoDone = stageCount('Demo Done') + stageCount('Proposal Sent') + won + lost;
const proposals = stageCount('Proposal Sent') + won + lost;

const pct = (a, b) => b ? Math.round(1000 * a / b) / 10 : 0;

return [{ json: {
  week_of: new Date().toISOString().slice(0, 10),
  duplicates: { groups: duplicates.length, detail: duplicates },
  incomplete: { detail: incomplete },
  stale: { count: staleCount, value: staleValue, worst_owner: worstOwner, by_owner: stale },
  funnel: { detail: funnel, open_deals: openDeals, won, lost,
            demo_to_proposal_pct: pct(proposals, demoDone),
            win_rate_pct: pct(won, won + lost) },
  deal_issues: { count: issues.length, detail: issues }
}}];

const d = $json;
const n = v => Number(v) || 0;
const arr = v => Array.isArray(v) ? v : (v ? JSON.parse(v) : []);

const funnel  = arr(d.funnel);
const owners  = arr(d.stale_by_owner);
const history = arr(d.history);

const eur = v => 'EUR ' + n(v).toLocaleString('de-DE');

// Previous week comes from the snapshot history (index 1 = the week before this one)
const prev = history[1] || null;
const delta = (now, before) => {
  if (!prev || before === undefined || before === null) return '';
  const diff = n(now) - n(before);
  if (diff === 0) return '<span class="flat">no change</span>';
  const cls = diff > 0 ? 'up' : 'down';
  return `<span class="${cls}">${diff > 0 ? '+' : ''}${diff.toLocaleString('de-DE')} vs last week</span>`;
};

const maxDeals = Math.max(1, ...funnel.map(f => n(f.deals)));

const tile = (label, value, sub) =>
  `<div class="tile"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub || ''}</div></div>`;

const funnelRows = funnel.map(f => `
  <tr>
    <td class="stage">${f.stage}</td>
    <td class="barcell"><div class="bar" style="width:${Math.round(100 * n(f.deals) / maxDeals)}%"></div></td>
    <td class="num">${n(f.deals)}</td>
    <td class="num">${eur(f.value)}</td>
  </tr>`).join('');

const ownerRows = owners.map(o => `
  <tr>
    <td>${o.owner || '(no owner)'}</td>
    <td class="num">${n(o.stale_deals)}</td>
    <td class="num">${eur(o.value_at_risk)}</td>
  </tr>`).join('');

const historyRows = history.map(h => `
  <tr>
    <td>${String(h.week_of).slice(0, 10)}</td>
    <td class="num">${n(h.stale_deals)}</td>
    <td class="num">${eur(h.stale_value)}</td>
    <td class="num">${n(h.duplicates)}</td>
    <td class="num">${n(h.open_deals)}</td>
  </tr>`).join('');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>CRM Health Dashboard</title>
<style>
  :root { --bg:#f6f7f9; --card:#fff; --ink:#1a1a1a; --muted:#6b7280;
          --line:#e5e7eb; --bad:#b42b2b; --good:#0e6b3a; }
  * { box-sizing:border-box; }
  body { margin:0; padding:32px 20px; background:var(--bg); color:var(--ink);
         font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; }
  .wrap { max-width:960px; margin:0 auto; }
  h1 { font-size:22px; margin:0 0 4px; }
  .date { color:var(--muted); font-size:13px; margin-bottom:24px; }
  h2 { font-size:15px; margin:0 0 12px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); }
  .tiles { display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:14px; margin-bottom:28px; }
  .tile { background:var(--card); border:1px solid var(--line); border-radius:10px; padding:16px; }
  .label { font-size:12px; color:var(--muted); text-transform:uppercase; letter-spacing:.04em; }
  .value { font-size:26px; font-weight:600; margin:6px 0 2px; }
  .sub { font-size:12px; color:var(--muted); }
  .card { background:var(--card); border:1px solid var(--line); border-radius:10px; padding:18px; margin-bottom:22px; }
  table { width:100%; border-collapse:collapse; font-size:14px; }
  th { text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:.04em;
       color:var(--muted); font-weight:600; padding:0 8px 8px 0; }
  td { padding:7px 8px 7px 0; border-top:1px solid var(--line); }
  .num { text-align:right; white-space:nowrap; }
  .stage { width:130px; }
  .barcell { width:45%; }
  .bar { height:10px; background:var(--good); border-radius:5px; min-width:3px; }
  .up { color:var(--bad); } .down { color:var(--good); } .flat { color:var(--muted); }
  footer { color:var(--muted); font-size:12px; text-align:center; margin-top:28px; }
  @media (max-width:560px){ .barcell{display:none;} .stage{width:auto;} }
</style>
</head>
<body>
<div class="wrap">
  <h1>CRM Health Dashboard</h1>
  <div class="date">Generated ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC</div>

  <div class="tiles">
    ${tile('Stale deals', n(d.stale_deals), prev ? delta(d.stale_deals, prev.stale_deals) : 'no activity 30+ days')}
    ${tile('Value at risk', eur(d.stale_value), prev ? delta(d.stale_value, prev.stale_value) : 'in stale deals')}
    ${tile('Duplicate groups', n(d.duplicate_groups), prev ? delta(d.duplicate_groups, prev.duplicates) : 'same person, several records')}
    ${tile('Incomplete contacts', n(d.incomplete_contacts), 'of ' + n(d.total_contacts) + ' total')}
  </div>

  <div class="card">
    <h2>Pipeline by stage</h2>
    <table>
      <tr><th>Stage</th><th></th><th class="num">Deals</th><th class="num">Value</th></tr>
      ${funnelRows}
    </table>
  </div>

  <div class="card">
    <h2>Stale deals by owner</h2>
    <table>
      <tr><th>Owner</th><th class="num">Deals</th><th class="num">Value at risk</th></tr>
      ${ownerRows || '<tr><td colspan="3">Nothing stale. Good week.</td></tr>'}
    </table>
  </div>

  <div class="card">
    <h2>Week over week</h2>
    <table>
      <tr><th>Week of</th><th class="num">Stale</th><th class="num">At risk</th><th class="num">Duplicates</th><th class="num">Open deals</th></tr>
      ${historyRows || '<tr><td colspan="5">No history yet.</td></tr>'}
    </table>
  </div>

  <footer>${n(d.total_contacts)} contacts, ${n(d.total_deals)} deals. Built with n8n and Postgres.</footer>
</div>
</body>
</html>`;

return [{ json: { html } }];

// Territory balance check: compares each AE to the team average.
// Index 100 = exactly average. Above 125 = overloaded, below 75 = underloaded.
const HIGH = 125, LOW = 75;

const rows = $input.all().map(i => i.json);
const num = v => Number(v) || 0;

const owned   = rows.filter(r => r.owner !== '(no owner)');
const unowned = rows.find(r => r.owner === '(no owner)');

const avg = f => owned.length
  ? owned.reduce((s, r) => s + num(r[f]), 0) / owned.length : 0;
const avgAccounts = avg('accounts');
const avgPipeline = avg('open_pipeline');

const index  = (v, a) => a ? Math.round(100 * num(v) / a) : 0;
const status = i => i > HIGH ? 'overloaded' : i < LOW ? 'underloaded' : 'balanced';

const reps = owned.map(r => {
  const account_index  = index(r.accounts, avgAccounts);
  const pipeline_index = index(r.open_pipeline, avgPipeline);
  return {
    owner: r.owner,
    accounts: num(r.accounts),
    open_deals: num(r.open_deals),
    open_pipeline: num(r.open_pipeline),
    account_index, pipeline_index,
    account_status: status(account_index),
    pipeline_status: status(pipeline_index)
  };
});

const flagged = reps.filter(r =>
  r.account_status !== 'balanced' || r.pipeline_status !== 'balanced');

return [{ json: {
  avg_accounts: Math.round(avgAccounts),
  avg_open_pipeline: Math.round(avgPipeline),
  reps,
  flagged,
  unowned: { accounts: num(unowned && unowned.accounts),
             open_pipeline: num(unowned && unowned.open_pipeline) }
}}];

const t = $input.first().json;
const eur = n => 'EUR ' + Math.round(Number(n) || 0).toLocaleString('en-US');

const lines = [];
lines.push(`Territory balance: ${t.reps.length} AEs, on average ${t.avg_accounts} accounts and ${eur(t.avg_open_pipeline)} open pipeline each.`);
lines.push('');

// One line per AE
for (const r of t.reps) {
  lines.push(`${r.owner}: ${r.accounts} accounts (${r.account_index}% of average, ${r.account_status}), ` +
             `${eur(r.open_pipeline)} open pipeline in ${r.open_deals} deals (${r.pipeline_index}% of average, ${r.pipeline_status}).`);
}

// What to do about it
const actions = [];
for (const r of t.reps) {
  if (r.account_index > 100 && r.pipeline_index < 75) {
    actions.push(`${r.owner} has an above-average account count but well below-average pipeline. Check account quality and follow-up before adding more accounts.`);
  } else if (r.pipeline_status === 'overloaded') {
    actions.push(`${r.owner} carries more pipeline than average. Check capacity and consider moving some deals.`);
  } else if (r.pipeline_status === 'underloaded') {
    actions.push(`${r.owner} has less pipeline than average. Consider assigning more opportunities or focusing on pipeline generation.`);
  }
  if (r.account_status === 'overloaded') {
    actions.push(`${r.owner} holds more accounts than average. Consider moving some to a rep with room.`);
  } else if (r.account_status === 'underloaded') {
    actions.push(`${r.owner} holds fewer accounts than average and has room for more.`);
  }
}
if (t.unowned.accounts > 0) {
  actions.push(`${t.unowned.accounts} accounts (${eur(t.unowned.open_pipeline)} open pipeline) have no owner. Assign them.`);
}

lines.push('');
lines.push(actions.length ? 'What to look at:' : 'All territories are within the balanced range.');
for (const a of actions) lines.push('- ' + a);

const week_of = new Date().toISOString().slice(0, 10);   // e.g. 2026-10-04
return [{ json: { week_of, summary: lines.join('\n') } }];
